/*
 * hal/leds.c — WS2812 strip driver (see leds.h)
 */
#include "pico/stdlib.h"
#include "hardware/pio.h"
#include "ws2812.pio.h"   /* generated by pioasm */
#include "leds.h"

static PIO  led_pio = pio1;
static uint led_sm;

/* GRB word as sent on the wire (before brightness scaling): one writer per
 * slot at a time, 32-bit aligned -> no tearing within a pixel. */
static volatile uint32_t fb[LEDS_COUNT];

void leds_init(void) {
    uint offset = pio_add_program(led_pio, &ws2812_program);
    led_sm = (uint)pio_claim_unused_sm(led_pio, true);
    ws2812_program_init(led_pio, led_sm, offset, LEDS_PIN, 800000.0f);
    leds_clear();
    leds_show();
}

void leds_set(uint8_t i, uint8_t r, uint8_t g, uint8_t b) {
    if (i >= LEDS_COUNT) return;
    fb[i] = ((uint32_t)g << 16) | ((uint32_t)r << 8) | b;
}

void leds_clear(void) {
    for (uint8_t i = 0; i < LEDS_COUNT; i++) fb[i] = 0;
}

void leds_show(void) {
    for (uint8_t i = 0; i < LEDS_COUNT; i++) {
        uint32_t p = fb[i];
        uint32_t g = (((p >> 16) & 0xFF) * LEDS_BRIGHTNESS) / 255;
        uint32_t r = (((p >> 8)  & 0xFF) * LEDS_BRIGHTNESS) / 255;
        uint32_t b = (( p        & 0xFF) * LEDS_BRIGHTNESS) / 255;
        pio_sm_put_blocking(led_pio, led_sm, (g << 24) | (r << 16) | (b << 8));
    }
    /* >280 µs idle low = latch; guaranteed by the 20 ms main-loop period. */
}
